type Section="today"|"patrols"|"projects"|"stottly"|"week"|"watch"|"month"|"long";
type Task={id:string;title:string;section:Section;day?:string;due?:string;recurring?:boolean;group?:string;energy?:"Low"|"Medium"|"High";priority?:boolean;done:boolean;created:string;completed?:string};
type Meal={logged:boolean;note:string};
type OuraDay={sleepScore?:number;readinessScore?:number;activityScore?:number;stressMinutes?:number;recoveryMinutes?:number;resilience?:string};
type Health={date:string;sleep:string;weight:string;energy:number;mood:number;hydration:number;bloodSugar:string;exercise:string;yoga:string;hygiene:string[];notes:string;emotion:string;emotionIntensity:number;anxiety:number;stress:number;regulated:number;trigger:string;response:string;helped:string;medsTaken:string[];meals:{breakfast:Meal;lunch:Meal;dinner:Meal};oura?:OuraDay};
type InterviewPeriod="breakfast"|"lunch"|"dinner";
type Morning={date:string;period:InterviewPeriod;sleepQuality:string;energy:number;emotion:string;focus:string;needs:string[];meal:string};
type Relationship={date:string;actions:string[];hardestTime:string;whatSheNeeds:string;lovedAnswer:string;note:string};
type Outcome={id:string;title:string;area:"Business"|"Personal"|"Health"|"Family";status:"On track"|"Attention"|"Blocked"|"Paused";progress:number;nextAction:string;deadline:string;revenuePotential:number;energy:"Low"|"Medium"|"High"};
type Opportunity={id:string;name:string;value:number;stage:"Lead"|"Conversation"|"Proposal"|"Won";nextAction:string;followUp:string};
type Decision={id:string;date:string;decision:string;why:string;reviewDate:string;result:string};
type Review={id:string;date:string;moved:string;money:string;stalled:string;drained:string;stop:string;nextThree:string};
type Capture={id:string;date:string;kind:"Task"|"Idea"|"Opportunity"|"Note";text:string;processed:boolean};
type State={tasks:Task[];health:Health[];revenue:{date:string;amount:number;source:string}[];mornings:Morning[];medNames:string[];relationships:Relationship[];lastDailyReset:string;dailyHistory:{date:string;completed:string[]}[];interviewReminders:boolean;bigThree:string[];monthlyRevenueTarget:number;outcomes:Outcome[];opportunities:Opportunity[];decisions:Decision[];reviews:Review[];captures:Capture[]};
type View="home"|"week"|"business"|"strategy"|"review"|"health"|"relationship"|"google"|"kpi"|"data";

